function adHelp(){message('About this training snap-in','Windows-style Active Directory Users and Computers\n\nImplemented: users, groups, OUs, computer placement, properties, memberships, account controls, reset-password simulation, search, move/copy/rename/delete, Advanced Features attributes, and list export.\n\nThis is not RSAT or AD DS. Delegation ACL enforcement, replication, Kerberos, trusts, certificates, Exchange, and legacy RDS tabs require a real Windows lab. Unsupported operations are not represented as successful.');}
function newObjectMenu(){return [{label:'User',icon:'♟',action:()=>newObject('user')},{label:'Group',icon:'♟♟',action:()=>newObject('group')},{label:'Computer',icon:'▣',action:()=>newDirectoryExtra('computer')},{label:'Contact',icon:'♙',action:()=>newDirectoryExtra('contact')},{label:'Organizational Unit',icon:'▰',action:()=>newObject('ou')}];}
