function newDirectoryExtra(type){dialog('New Object - '+(type==='computer'?'Computer':'Contact'),`<p>Create in: ${E(adPath||'corp.example.test')}</p><div class="form-grid">${field('Name:','name','')}${field(type==='computer'?'Description:':'E-mail:','value','')}</div><div id="extraADerror" class="dialog-error"></div>`,[{label:'OK',action:()=>{const v=formValues();try{createDirectoryExtra(type,v.name,adPath,v.value);closeDialog();renderDirectory();}catch(e){$('#extraADerror').textContent=e.message;}}},{label:'Cancel',action:closeDialog}]);}
