function contactProperties(o){dialog(o.name+' Properties',`<div class="form-grid">${field('Display name:','name',o.name)}${field('E-mail:','email',o.ref?.email||'')}${field('Description:','description',o.ref?.description||'')}</div>`,[{label:'OK',action:()=>{const extra=state.directoryExtras.find(x=>x.id===o.id);const v=formValues();if(v.name.trim())extra.name=v.name.trim();extra.email=v.email;extra.description=v.description;save();closeDialog();renderDirectory();}},{label:'Cancel',action:closeDialog}]);}
