function properties(o){if(o.type==='user')userProperties(findUser(o.id));else if(o.type==='group')groupProperties(o.ref||allGroups().find(g=>g.name===o.id));else if(o.type==='computer'){if((state.directoryExtras||[]).some(x=>x.id===o.id))extraComputerProperties(o);else computerProperties(o);}else if(o.type==='contact')contactProperties(o);else containerProperties(o.id);}
function containerProperties(path,tab='General',draft=null){state.ouMeta ||= {};const meta=draft||{description:'',managedBy:'',...state.ouMeta[path],protected:state.ouProtected[path]!==false},tabs=['General','Managed By','Object',...(adAdvanced?['Security']:[]),'Group Policy'];let body;if(tab==='General')body=`<div class="form-grid">${field('Name:','ouName',path.split('/').at(-1)||'corp.example.test','text',true)}${field('Description:','description',meta.description)}</div>`;else if(tab==='Managed By')body=`<div class="form-grid"><label>Managed by:</label><select data-field="managedBy"><option value="">(none)</option>${state.users.map(u=>`<option value="${u.sam}" ${meta.managedBy===u.sam?'selected':''}>${E(u.name)}</option>`).join('')}</select></div><p class="dialog-notice">Directory contact metadata only; no delegated rights are granted.</p>`;else if(tab==='Object')body=`<div class="form-grid">${field('Canonical name:','canonical','corp.example.test/'+path,'text',true)}${field('Object class:','class',path?'organizationalUnit':'domainDNS','text',true)}${field('Distinguished name:','dn',pathDN(path),'text',true)}</div>${check('Protect object from accidental deletion','protected',meta.protected)}`;else if(tab==='Security')body='<div class="dialog-list"><label>SYSTEM</label><label>CORP\\Domain Admins</label><label>Authenticated Users</label></div><p class="dialog-notice">Read-only teaching view. Actual AD object ACLs, effective delegation, and inherited security are not implemented.</p>';else body=`<p>Linked Group Policy Objects:</p><div class="dialog-list">${path==='Lab/Workstations'?'<label>LAB-Workstation-Baseline</label>':'<p>(No directly linked GPO modeled)</p>'}</div><p class="dialog-notice">Client scope and policy refresh are practiced through Settings or PowerShell. Full Group Policy Management requires Windows.</p>`;const capture=()=>{const values=formValues();for(const key of ['description','managedBy','protected'])if(key in values)meta[key]=values[key];};const apply=()=>{capture();state.ouMeta[path]={description:meta.description,managedBy:meta.managedBy};state.ouProtected[path]=meta.protected;save();};dialog((path.split('/').at(-1)||'corp.example.test')+' Properties',body,[{label:'OK',action:()=>{apply();closeDialog();}},{label:'Cancel',action:closeDialog},{label:'Apply',action:apply}],tabs.map(t=>`<button data-ou-tab="${t}" class="${t===tab?'selected':''}">${t}</button>`).join(''));$$('[data-ou-tab]',dialogRoot).forEach(b=>b.onclick=()=>{capture();containerProperties(path,b.dataset.ouTab,meta);});}
