function parse(segment){const parts=tokenize(segment);const raw=parts.shift()||'';const name=aliases[raw.toLowerCase()]||Object.keys(commandHelp).find(n=>n.toLowerCase()===raw.toLowerCase())||raw;const p={},pos=[];for(let i=0;i<parts.length;i++){const token=parts[i];if(/^-[a-zA-Z]/.test(token)){const match=token.match(/^-([^:]+)(?::(.*))?$/);const key=match[1].toLowerCase();if(Object.hasOwn(p,key))psError('Parameter specified more than once: '+key);if(match[2]!==undefined)p[key]=valueOf(match[2]);else if(parts[i+1]!==undefined&&!/^-[a-zA-Z]/.test(parts[i+1]))p[key]=valueOf(parts[++i]);else p[key]=true;}else pos.push(valueOf(token));}return {name,p,pos,raw,segment};}
