function parseCSV(text){const lines=String(text).trim().split(/\r?\n/);function row(line){const values=[];let v='',quote=false;for(let i=0;i<line.length;i++){if(line[i]==='"'){if(quote&&line[i+1]==='"'){v+='"';i++;}else quote=!quote;}else if(line[i]===','&&!quote){values.push(v);v='';}else v+=line[i];}values.push(v);return values;}const keys=row(lines.shift()||'');return lines.filter(Boolean).map(line=>Object.fromEntries(row(line).map((v,i)=>[keys[i]||String(i),v])));}
function formatPS(res){const rows=res.data;if(!rows.length)return '';if(rows.every(r=>r===null||typeof r!=='object'))return rows.map(v=>v===true?'True':v===false?'False':String(v??'')).join('\n');const props=res.properties||[...new Set(rows.flatMap(r=>r&&typeof r==='object'?Object.keys(r):[]))];const text=v=>Array.isArray(v)?'{'+v.join(', ')+'}':v===true?'True':v===false?'False':String(v??'');if(res.format==='list')return rows.map(r=>props.map(k=>k.padEnd(Math.max(...props.map(p=>p.length)))+' : '+text(getProperty(r,k))).join('\n')).join('\n\n');const widths=props.map(k=>Math.min(65,Math.max(k.length,...rows.map(r=>text(getProperty(r,k)).length))));return [props.map((p,i)=>p.padEnd(widths[i])).join('  '),props.map((_,i)=>'-'.repeat(widths[i])).join('  '),...rows.map(r=>props.map((p,i)=>text(getProperty(r,p)).slice(0,widths[i]).padEnd(widths[i])).join('  '))].join('\n');}
runCommand=command=>{try{let output=[],last=result();for(let statement of splitTop(String(command),';')){if(!statement||statement.startsWith('#'))continue;let assignment=null;const a=statement.match(/^\$(\w+)\s*=\s*(.+)$/s);if(a){assignment=a[1].toLowerCase();statement=a[2];}if(/^\$\w+(?:\.\w+)?$/.test(statement)){last=result(valueOf(statement));}else{let input=[];for(const segment of splitTop(statement,'|')){if(!segment)psError('An empty pipe element is not allowed.');last=execute(parse(segment),input);input=last.data;}}if(assignment){variables.set(assignment,last.data.length===1?last.data[0]:last.data);}else{const text=formatPS(last);if(text)output.push(text);}}save();return {output:output.join('\n\n'),error:false,clear:!!last.clear};}catch(error){return {output:String(error.message)+'\n    + CategoryInfo          : TrainingShellError\n    + FullyQualifiedErrorId : SimulatedCommandError',error:true};}};
const oldRenderTerminal=renderTerminal;
renderTerminal=()=>{oldRenderTerminal();$('.term-banner').innerHTML='Windows PowerShell<br>Windows-style training shell — no host commands are executed.<br>Type help to see the supported command syntax.<br>';$('#terminalForm label').textContent='PS '+cwd+'> ';const form=$('#terminalForm');form.onsubmit=e=>{e.preventDefault();const input=$('#terminalInput'),command=input.value.trim();if(!command)return;input.value='';termHistory.push(command);termIndex=termHistory.length;const response=runCommand(command);if(!frames.has('terminal'))return;if(response.clear){state.history=[];if($('#terminalOutput'))$('#terminalOutput').replaceChildren();}else{state.history.push({command,...response});state.history=state.history.slice(-120);const terminalFrame=frames.get('terminal');if(terminalFrame&&!terminalFrame.classList.contains('hidden')){const prior=activeFrame;activate('terminal');appendTerminal(command,response.output,response.error);if(prior!== 'terminal')activate(prior);}}save();if(activeFrame==='terminal'){$('#terminalForm label').textContent='PS '+cwd+'> ';input.scrollIntoView({block:'nearest'});}};const input=$('#terminalInput'),oldKeys=input.onkeydown;input.onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const raw=input.value,head=raw.split(/\s/)[0];const matches=Object.keys(commandHelp).filter(n=>n.toLowerCase().startsWith(head.toLowerCase()));if(matches.length===1)input.value=matches[0]+raw.slice(head.length);else if(matches.length)toast(matches.slice(0,8).join('  '));}else if(e.ctrlKey&&e.key.toLowerCase()==='c'){if(!window.getSelection?.()?.toString()){e.preventDefault();input.value='';appendTerminal('','^C',false);}}else oldKeys?.(e);};$('.terminal').oncontextmenu=e=>{e.preventDefault();menu([{label:'Copy selection',action:()=>{const text=window.getSelection?.()?.toString();if(text&&navigator.clipboard)navigator.clipboard.writeText(text).catch(()=>toast('Use Ctrl+C to copy the selection.'));else toast('Select text, then use Ctrl+C.');}},{label:'Paste',action:async()=>{try{input.value+=await navigator.clipboard.readText();input.focus();}catch{toast('Click the command field and use Ctrl+V to paste.');}}},{separator:true},{label:'Clear screen',action:()=>{state.history=[];save();renderTerminal();}},{label:'Command reference',action:()=>message('PowerShell command reference',runCommand('help').output)}],e.clientX,e.clientY);};};

